<?php
namespace App\Services; use App\Models\TrainingSession; use Illuminate\Http\UploadedFile; use Illuminate\Support\Facades\Storage; use Illuminate\Validation\ValidationException;
class TrainingEvidenceService { public function store(TrainingSession$s,UploadedFile$file,array$data,int$user){if($s->status==='closed')throw ValidationException::withMessages(['file'=>'Una sesión cerrada no admite nuevas evidencias sin corrección formal.']);$path=$file->store("training/evidences/{$s->uuid}",config('training.evidence_disk','local'));$e=$s->evidences()->create(['company_id'=>$s->company_id,'evidence_type'=>$data['evidence_type'],'title'=>$data['title'],'file_path'=>$path,'original_name'=>$file->getClientOriginalName(),'mime_type'=>$file->getMimeType(),'file_size'=>$file->getSize(),'file_hash'=>hash_file('sha256',$file->getRealPath()),'is_required'=>$data['is_required']??false,'uploaded_by'=>$user]);app(TrainingSessionService::class)->audit($s,'training_evidence_added',$user,['evidence_id'=>$e->id]);return$e;} }
